  CREATE   PROCEDURE [Mapping].[usp_MergeValidationClusters]      @chrEntity    SYSNAME,      @chrGroupCode NVARCHAR(50),      @payload      NVARCHAR(MAX)  AS  BEGIN      SET NOCOUNT ON;        DECLARE @db  SYSNAME = N'dp_validation';   -- <<< confirm      DECLARE @msg NVARCHAR(400);        ------------------------------------------------------------------      -- Guard 1: entity must exist as a schema in the validation database      ------------------------------------------------------------------      DECLARE @schemaExists INT;      DECLARE @schk NVARCHAR(MAX) =          N'SELECT @x = COUNT(*) FROM ' + QUOTENAME(@db) + N'.sys.schemas WHERE name = @e;';      EXEC sp_executesql @schk, N'@e SYSNAME, @x INT OUTPUT', @e = @chrEntity, @x = @schemaExists OUTPUT;        IF @schemaExists = 0      BEGIN          SET @msg = N'Entity schema ' + @chrEntity + N' does not exist in ' + @db + N'.';          THROW 50001, @msg, 1;      END;        ------------------------------------------------------------------      -- Guard 2: group code must be supplied and exist in the entity Validation      ------------------------------------------------------------------      IF NULLIF(LTRIM(RTRIM(@chrGroupCode)), N'') IS NULL      BEGIN          THROW 50002, N'Group code is required.', 1;      END;        -- Group code is scoped by the code prefix: <groupcode>_<source key>      DECLARE @pat NVARCHAR(60) = LTRIM(RTRIM(@chrGroupCode)) + N'\_%';      DECLARE @esc NCHAR(1)     = N'\';      DECLARE @tgt NVARCHAR(300) = QUOTENAME(@db) + N'.' + QUOTENAME(@chrEntity) + N'.Validation';      DECLARE @cnt INT;      DECLARE @chk NVARCHAR(MAX) =          N'SELECT @c = COUNT(*) FROM ' + @tgt + N' WHERE [code] LIKE @pat ESCAPE @esc;';        EXEC sp_executesql @chk, N'@pat NVARCHAR(60), @esc NCHAR(1), @c INT OUTPUT', @pat = @pat, @esc = @esc, @c = @cnt OUTPUT;        IF @cnt = 0      BEGIN          SET @msg = N'Group code ' + @chrGroupCode + N' has no rows in entity ' + @chrEntity + N'.';          THROW 50003, @msg, 1;      END;        ------------------------------------------------------------------      -- Static SQL: parse the /api/dedup/cluster-block response      ------------------------------------------------------------------      IF OBJECT_ID(N'tempdb..#src') IS NOT NULL DROP TABLE #src;        SELECT *      INTO #src      FROM OPENJSON(@payload, N'$.rows')      WITH (          row_id       NVARCHAR(100) N'$.row_id',          block_id     NVARCHAR(100) N'$.block_id',          cluster_id   NVARCHAR(100) N'$.cluster_id',    -- content hash string, not INT          routing      NVARCHAR(30)  N'$.routing',          signature_id NVARCHAR(100) N'$.signature_id',          confidence   FLOAT         N'$.confidence',          reasoning    NVARCHAR(MAX) N'$.reasoning'      );        ------------------------------------------------------------------      -- Dynamic SQL: only database and schema are spliced in      ------------------------------------------------------------------      DECLARE @sql NVARCHAR(MAX) = N'      MERGE ' + @tgt + N' AS tgt      USING #src AS src         ON tgt.Customer = src.row_id        AND tgt.[code] LIKE @pat ESCAPE @esc      WHEN MATCHED THEN UPDATE SET          tgt.[Block ID]     = src.block_id,          tgt.[Cluster ID]   = src.cluster_id,          tgt.[Routing]      = src.routing,          tgt.[Signature ID] = src.signature_id,          tgt.[Confidence]   = src.confidence,          tgt.[Reasoning]    = src.reasoning;';        EXEC sp_executesql @sql, N'@pat NVARCHAR(60), @esc NCHAR(1)', @pat = @pat, @esc = @esc;        DROP TABLE #src;  END;  